let cloudRecordPages={profiles:{rows:[],total:0,offset:0,search:''},events:{rows:[],total:0,offset:0,search:''},audit:{rows:[],total:0,offset:0,search:''}},cloudRecordSearchTimers={},cloudRecordRequests={};
async function cloudLoadRecordPage(kind,offset=0,search=cloudRecordPages[kind].search){const request=(cloudRecordRequests[kind]||0)+1;cloudRecordRequests[kind]=request;try{const data=await cloudRequest('/rest/v1/rpc/shams_admin_records',{p_kind:kind,p_search:search,p_offset:Math.max(0,offset)});if(request!==cloudRecordRequests[kind])return;cloudRecordPages[kind]={...data,search};const container=document.querySelector('#cloudRecords-'+kind);if(container)container.innerHTML=cloudRecordsHTML(kind)}catch(e){toast(e.message)}}
function cloudSearchRecords(kind,search){clearTimeout(cloudRecordSearchTimers[kind]);cloudRecordSearchTimers[kind]=setTimeout(()=>cloudLoadRecordPage(kind,0,search),350)}
loadCloudAdmin=async function(){if(!cloudState.admin)return;try{cloudAdminData=await cloudRequest('/rest/v1/rpc/shams_admin_overview',{});await Promise.all(['profiles','events','audit'].map(k=>cloudLoadRecordPage(k,cloudRecordPages[k].offset)));if(route==='cloudadmin')render()}catch(e){toast(e.message)}};
function cloudRecordsHTML(kind){const page=cloudRecordPages[kind],rows=page.rows;let html;if(kind==='profiles')html=rows.map(p=>`<article class="cloud-user"><strong>${esc(p.display_name||p.email)} ${p.is_admin?'✦':''}</strong><small>${esc(p.email)}</small><small>Qeydiyyat: ${esc(p.created_at)}<br>Son giriş: ${esc(p.last_sign_in_at||'—')}</small>${p.id===cloudState.session.user.id?'':`<button class="secondarybtn" onclick="toggleCloudUser('${p.id}',${!p.disabled})">${p.disabled?'Girişi bərpa et':'Bulud girişini məhdudlaşdır'}</button>`}</article>`).join('');else if(kind==='events')html=rows.map(e=>`<article class="cloud-log"><strong>${esc(e.kind)}</strong><span>${esc(e.email||e.user_id||'—')}</span><small>${esc(e.created_at)} · ${Number(e.details?.count)||0}</small></article>`).join('');else html=rows.map(a=>`<p>${esc(a.action)} · ${esc(a.target||'')}<small>${esc(a.created_at)}</small></p>`).join('');return (html||`<p>${cw('empty')}</p>`)+`<div class="module-pagination"><button class="secondarybtn" onclick="cloudLoadRecordPage('${kind}',${Math.max(0,page.offset-50)})" ${page.offset?'':'disabled'}>←</button><span>${page.total?Math.floor(page.offset/50)+1:0} / ${Math.ceil(page.total/50)} · ${page.total}</span><button class="secondarybtn" onclick="cloudLoadRecordPage('${kind}',${page.offset+50})" ${page.offset+50<page.total?'':'disabled'}>→</button></div>`}
cloudAdminPage=function(){if(!cloudState.admin)return `<div data-localized="true">${head(cw('admin'),'')}<section class="card"><p>${cw('signin')}</p><button class="goldbtn" onclick="go('account')">${cw('account')} →</button></section></div>`;if(!cloudAdminData){setTimeout(loadCloudAdmin,0);return head(cw('admin'),'')+'<p>…</p>'}const d=cloudAdminData;return `<div class="cloud-admin" data-localized="true">${head(cw('admin'),'')}<div class="module-actions"><button class="secondarybtn" onclick="loadCloudAdmin()">↻ Yenilə</button><button class="goldbtn" onclick="editCloudContent()">＋ Məzmun</button></div><div class="module-stats"><div><b>${d.total_users}</b><span>Qeydiyyat</span></div><div><b>${d.disabled_users}</b><span>Məhdud hesab</span></div><div><b>${d.content.length}</b><span>Məzmun</span></div></div>${[['profiles','İstifadəçilər və qeydiyyat tarixçəsi'],['events','Əlavələr və fəaliyyətlər'],['audit','Admin audit tarixçəsi']].map(([k,label])=>`<details class="card" ${k==='profiles'?'open':''}><summary>${label}</summary><input type="search" placeholder="Axtar…" value="${esc(cloudRecordPages[k].search)}" oninput="cloudSearchRecords('${k}',this.value)"><div id="cloudRecords-${k}">${cloudRecordsHTML(k)}</div></details>`).join('')}<details class="card"><summary>Tətbiqin dua və elanları</summary>${d.content.map(c=>`<button class="row" onclick="editCloudContent('${c.id}')"><strong class="grow">${esc(c.payload.title)}</strong><span>${c.published?'●':'○'} ${esc(c.kind)}</span></button>`).join('')||cw('empty')}</details><p class="notice">Şəxsi dua mətnləri və ehtiyat nüsxələri yalnız istifadəçiyə açıqdır. Tarixçə səhifələnir, köhnə qeydlər də axtarılır.</p></div>`};
